    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Apollo 11 (July 16–24, 1969) was the American spaceflight that first landed humans on the Moon, and the fifth crewed mission of NASA''s Apollo program. The mission was crewed by Commander Neil Armstrong, Command Module Pilot Michael Collins, and Lunar Module Pilot Edwin \"Buzz\" Aldrin, all of whom were on their second and final spaceflight."}]}]},"keywords":[{"id":"kw1","text":"Pilot"},{"id":"kw2","text":"Module"},{"id":"kw3","text":"American"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Apollo 11","pageid":662,"revision_id":1357361725,"url":"https://en.wikipedia.org/wiki/Apollo_11","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
