    'd1000001-0000-4000-8000-100100000005',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Alan Mathison Turing (; 23 June 1912 – 7 June 1954) was an English mathematician, computer scientist, logician, cryptanalyst, philosopher and theoretical biologist."}]},{"type":"paragraph","content":[{"type":"text","text":"He was highly influential in the development of theoretical computer science, providing a formalisation of the concepts of algorithm and computation with the Turing machine, which can be considered a model of a general-purpose computer. Turing is widely considered to be the father of theoretical computer science. Born in London, Turing was raised in southern England."}]}]},"keywords":[{"id":"kw1","text":"23 June 1912"},{"id":"kw2","text":"June"},{"id":"kw3","text":"considered"},{"id":"kw4","text":"London"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Alan Turing","pageid":1208,"revision_id":1362088307,"url":"https://en.wikipedia.org/wiki/Alan_Turing","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
