  (
    'd1000001-0000-4000-8000-100100000007',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Sir Isaac Newton ( ; (1643-01-04)4 January 1643 [O. S. 25 December 1642] – 31 March [O. S. 20 March] 1727) was an English polymath who was a mathematician, physicist, astronomer, alchemist, theologian, author and inventor. He was a key figure in the Scientific Revolution and the Enlightenment that followed."}]},{"type":"paragraph","content":[{"type":"text","text":"His book Philosophiæ Naturalis Principia Mathematica (Mathematical Principles of Natural Philosophy), first published in 1687, achieved the first great unification in physics and established classical mechanics."}]}]},"keywords":[{"id":"kw1","text":"December"},{"id":"kw2","text":"Philosophi"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Isaac Newton","pageid":14627,"revision_id":1362116224,"url":"https://en.wikipedia.org/wiki/Isaac_Newton","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
