    'd1000001-0000-4000-8000-100100000008',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Industrial Revolution, sometimes called the First Industrial Revolution in contrast to the subsequent Second Industrial Revolution, was a transitional period of the global economy toward more widespread, efficient and stable manufacturing processes, succeeding the Second Agricultural Revolution."}]},{"type":"paragraph","content":[{"type":"text","text":"Beginning in Great Britain around 1760, the Industrial Revolution had spread to continental Europe and the United States by about 1840. Economic historians agree that the onset of the Industrial Revolution is the most important event in human history, comparable only to the adoption of agriculture with respect to material advancement."}]}]},"keywords":[{"id":"kw1","text":"States"},{"id":"kw2","text":"Revolution"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Industrial Revolution","pageid":14914,"revision_id":1360889925,"url":"https://en.wikipedia.org/wiki/Industrial_Revolution","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
