  (
    'd1000001-0000-4000-8000-100100000009',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The International Space Station (ISS) is a space station in low Earth orbit (LEO). It is the product of the International Space Station program and is operated by five partner space agencies: NASA (United States), Roscosmos (Russia), ESA (Europe), JAXA (Japan), and CSA (Canada)."}]},{"type":"paragraph","content":[{"type":"text","text":"It is the first space station built, maintained and crewed through international cooperation and the largest human spacecraft ever constructed. It is an orbital research station, where scientific experiments in microgravity are conducted and the space environment is studied. Since 2 November 2000, it has hosted the longest continuous presence of humans in space."}]}]},"keywords":[{"id":"kw1","text":"Europe"},{"id":"kw2","text":"Space"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"International Space Station","pageid":15043,"revision_id":1361768129,"url":"https://en.wikipedia.org/wiki/International_Space_Station","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
