  (
    'd1000001-0000-4000-8000-10010000000a',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Maria Salomea Skłodowska Curie (Polish: [ˈmarja salɔˈmɛa skwɔˈdɔfska kiˈri] ; née Skłodowska; 7 November 1867 – 4 July 1934), better known as Marie Curie ( KURE-ee; French: [maʁi kyʁi] ), was a Polish and naturalised-French physicist and chemist."}]},{"type":"paragraph","content":[{"type":"text","text":"She shared the 1903 Nobel Prize in Physics with her husband, Pierre Curie, \"for their joint researches on the radioactivity phenomena discovered by Professor Henri Becquerel\". She won the 1911 Nobel Prize in Chemistry \"[for] the discovery of the elements radium and polonium, by the isolation of radium and the study of the nature and compounds of this remarkable element\"."}]}]},"keywords":[{"id":"kw1","text":"Physics"},{"id":"kw2","text":"Chemistry"},{"id":"kw3","text":"Nobel"},{"id":"kw4","text":"Professor"},{"id":"kw5","text":"Curie"}],"difficulty":"hard","source":{"provider":"wikipedia","title":"Marie Curie","pageid":20408,"revision_id":1361218051,"url":"https://en.wikipedia.org/wiki/Marie_Curie","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
