  (
    'd1000001-0000-4000-8000-10010000000b',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Magna Carta (Medieval Latin for \"Great Charter\"), sometimes spelled Magna Charta, is a royal charter of rights sealed by King John of England at Runnymede, near Windsor, on 15 June 1215."}]},{"type":"paragraph","content":[{"type":"text","text":"First drafted by the Archbishop of Canterbury, Cardinal Stephen Langton, to make peace between the unpopular king and a group of rebel barons who demanded that the King confirm the Charter of Liberties, it promised the protection of church rights, protection for the barons from illegal imprisonment, access to swift and impartial justice, and limitations on feudal payments to the Crown, to be implemented through a council of 25 barons."}]}]},"keywords":[{"id":"kw1","text":"Cardinal"},{"id":"kw2","text":"25"},{"id":"kw3","text":"Runnymede"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Magna Carta","pageid":20958,"revision_id":1358721085,"url":"https://en.wikipedia.org/wiki/Magna_Carta","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
