    'd1000001-0000-4000-8000-10010000000e',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Sydney Opera House is a multi-venue performing arts centre in Sydney, New South Wales, Australia. Located on the foreshore of Sydney Harbour, it is widely regarded as one of the world''s most famous and distinctive buildings, and a masterpiece of 20th-century architecture."}]},{"type":"paragraph","content":[{"type":"text","text":"Designed by Danish architect Jørn Utzon and completed by an Australian architectural team headed by Peter Hall, the building was formally opened by Queen Elizabeth II on 20 October 1973, 16 years after Utzon''s 1957 selection as winner of an international design competition."}]}]},"keywords":[{"id":"kw1","text":"Opera"},{"id":"kw2","text":"Elizabeth"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Sydney Opera House","pageid":28222,"revision_id":1359989632,"url":"https://en.wikipedia.org/wiki/Sydney_Opera_House","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
