    'd1000001-0000-4000-8000-100100000010',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Great Barrier Reef is the world''s largest coral reef system, composed of over 2,900 individual reefs and 900 islands stretching for over 2,300 kilometres (1,400 mi) over an area of approximately 344,400 square kilometres (133,000 mi2)."}]},{"type":"paragraph","content":[{"type":"text","text":"The reef is located in the Coral Sea, off the coast of Queensland, Australia, separated from the coast by a channel 160 kilometres (100 mi) wide in places and over 61 metres (200 ft) deep. The Great Barrier Reef can be seen from outer space and is the world''s biggest single structure made by living organisms."}]}]},"keywords":[{"id":"kw1","text":"2,900"},{"id":"kw2","text":"160"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Great Barrier Reef","pageid":70983,"revision_id":1357848546,"url":"https://en.wikipedia.org/wiki/Great_Barrier_Reef","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
