    'd1000001-0000-4000-8000-100100000011',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rosalind Elsie Franklin (25 July 1920 – 16 April 1958) was an English chemist and X-ray crystallographer. Her work was central to the understanding of the molecular structures of DNA (deoxyribonucleic acid), RNA (ribonucleic acid), viruses, coal, and graphite."}]},{"type":"paragraph","content":[{"type":"text","text":"Although her works on coal and viruses were appreciated in her lifetime, Franklin''s contributions to the discovery of the structure of DNA were largely unrecognised during her life, for which Franklin has been variously referred to as the \"wronged heroine\", the \"dark lady of DNA\", the \"forgotten heroine\", a \"feminist icon\", and the \"Sylvia Plath of molecular biology\"."}]}]},"keywords":[{"id":"kw1","text":"heroine"},{"id":"kw2","text":"Franklin"},{"id":"kw3","text":"DNA"},{"id":"kw4","text":"Sylvia"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Rosalind Franklin","pageid":90472,"revision_id":1358545736,"url":"https://en.wikipedia.org/wiki/Rosalind_Franklin","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
