  (
    'd1000001-0000-4000-8000-100100000012',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Florence Nightingale (; 12 May 1820 – 13 August 1910) was an English social reformer, statistician and the founder of modern nursing. Nightingale came to prominence while serving as a manager and trainer of nurses during the Crimean War, in which she organised care for wounded soldiers at Constantinople."}]},{"type":"paragraph","content":[{"type":"text","text":"She significantly reduced death rates by improving hygiene and living standards. Nightingale gave nursing a favourable reputation and became an icon of Victorian culture, especially in the persona of \"The Lady with the Lamp\" making ward rounds for wounded soldiers at night."}]}]},"keywords":[{"id":"kw1","text":"Victorian"},{"id":"kw2","text":"Lamp"},{"id":"kw3","text":"Crimean"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Florence Nightingale","pageid":100127,"revision_id":1358730807,"url":"https://en.wikipedia.org/wiki/Florence_Nightingale","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
