    'd1000001-0000-4000-8000-100100000013',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Kangaroo Island (Kaurna: Karta Pintingga, lit. ''Island of the Dead''), known colloquially as KI, is Australia''s third-largest island, after Tasmania and Melville Island. It lies in the state of South Australia, 112 km (70 mi) southwest of Adelaide. Its closest point to the mainland is Snapper Point in Backstairs Passage, which is 13. 5 km (8. 4 mi) from the Fleurieu Peninsula."}]},{"type":"paragraph","content":[{"type":"text","text":"Receiving over 200,000 visitors annually, Kangaroo Island is one of Australia''s most popular travel destinations, and was ranked as the second-best travel destination globally by Lonely Planet in 2024."}]}]},"keywords":[{"id":"kw1","text":"Adelaide"},{"id":"kw2","text":"Backstairs"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Kangaroo Island","pageid":161773,"revision_id":1356039121,"url":"https://en.wikipedia.org/wiki/Kangaroo_Island","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
