    'd1000001-0000-4000-8000-100100000014',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Charles Robert Darwin ( DAR-win; 12 February 1809 – 19 April 1882) was an English naturalist, geologist, and biologist, widely known for his contributions to evolutionary biology. His proposition that all species of life have descended from a common ancestor is now generally accepted and considered a fundamental scientific concept."}]},{"type":"paragraph","content":[{"type":"text","text":"In a joint presentation with Alfred Russel Wallace, he introduced his scientific theory that this branching pattern of evolution resulted from a process he called natural selection, in which the struggle for existence has a similar effect to the artificial selection involved in selective breeding."}]}]},"keywords":[{"id":"kw1","text":"Russel"},{"id":"kw2","text":"1809"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Charles Darwin","pageid":8145410,"revision_id":1360793412,"url":"https://en.wikipedia.org/wiki/Charles_Darwin","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
