  (
    'd1000001-0000-4000-8000-100100000015',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Eiffel Tower ( EYE-fəl; French: Tour Eiffel [tuʁ ɛfɛl] ) is a lattice tower on the Champ de Mars in Paris, France. It is named after the engineer Gustave Eiffel, whose company designed and built the tower from 1887 to 1889."}]},{"type":"paragraph","content":[{"type":"text","text":"Locally nicknamed \"La dame de fer\" (French for \"Iron Lady\") for its use of wrought iron, it was constructed as the centrepiece of the 1889 World''s Fair, and to crown the centennial anniversary of the French Revolution."}]}]},"keywords":[{"id":"kw1","text":"Revolution"},{"id":"kw2","text":"World''s"},{"id":"kw3","text":"EYE-fəl"},{"id":"kw4","text":"France"},{"id":"kw5","text":"1889"}],"difficulty":"hard","source":{"provider":"wikipedia","title":"Eiffel Tower","pageid":9232,"revision_id":1360653242,"url":"https://en.wikipedia.org/wiki/Eiffel_Tower","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
