    'd1000001-0000-4000-8000-100100000016',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The European Union (EU) is a political and economic union of 27 member states that are located primarily in Europe. A supranational union with a total area of 4,233,255 km2 (1,634,469 sq mi) and an estimated population of over 450 million as of 2025, its member states generated a nominal gross domestic product (GDP) of around €18."}]},{"type":"paragraph","content":[{"type":"text","text":"802 trillion in 2025, accounting for approximately one sixth of global economic output. The EU is often described as a sui generis political entity combining characteristics of both a federation and a confederation."}]}]},"keywords":[{"id":"kw1","text":"4,233,255"},{"id":"kw2","text":"2025"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"European Union","pageid":9317,"revision_id":1361991595,"url":"https://en.wikipedia.org/wiki/European_Union","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
