  (
    'd1000001-0000-4000-8000-100100000017',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An earthquake, also called a quake, tremor, or temblor, is the shaking of the Earth''s surface resulting from a sudden release of energy in the lithosphere that creates seismic waves."}]},{"type":"paragraph","content":[{"type":"text","text":"Earthquakes can range in intensity, from those so weak they cannot be felt, to those violent enough to propel objects and people into the air, damage critical infrastructure, and wreak destruction across entire cities. The seismic activity of an area is the frequency, type, and size of earthquakes experienced over a particular time."}]}]},"keywords":[{"id":"kw1","text":"seismic"},{"id":"kw2","text":"Earthquakes"},{"id":"kw3","text":"earthquake"},{"id":"kw4","text":"those"},{"id":"kw5","text":"Earth''s"}],"difficulty":"hard","source":{"provider":"wikipedia","title":"Earthquake","pageid":10106,"revision_id":1360651716,"url":"https://en.wikipedia.org/wiki/Earthquake","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
