  (
    'd1000001-0000-4000-8000-100100000018',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The FIFA World Cup, also known as the FIFA Men''s World Cup, is an international association football competition among the senior men''s national teams of the members of the Fédération Internationale de Football Association (FIFA), the sport''s global governing body."}]},{"type":"paragraph","content":[{"type":"text","text":"The tournament has been held every four years since the inaugural tournament in 1930, with the exception of 1942 and 1946 due to World War II. The reigning champions are Argentina, who won their third title at the 2022 World Cup by defeating France."}]}]},"keywords":[{"id":"kw1","text":"France"},{"id":"kw2","text":"1946"},{"id":"kw3","text":"FIFA"},{"id":"kw4","text":"Fédération"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"FIFA World Cup","pageid":11370,"revision_id":1362115352,"url":"https://en.wikipedia.org/wiki/FIFA_World_Cup","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
