  (
    'd1000001-0000-4000-8000-100100000019',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Jane Austen ( OST-in, AW-stin; 16 December 1775 – 18 July 1817) was an English writer known primarily for her six novels, which implicitly interpret, critique, and comment on the English landed gentry at the end of the 18th century. Austen''s plots often explore the dependence of women on marriage for the pursuit of favourable social standing and economic security."}]},{"type":"paragraph","content":[{"type":"text","text":"Her works are implicit critiques of the novels of sensibility of the second half of the 18th century and are part of the transition to 19th-century literary realism. Her use of social commentary, realism, wit, and irony have earned her acclaim amongst critics and scholars. Austen wrote major novels before the age of 22, but she was not published until she was 35."}]}]},"keywords":[{"id":"kw1","text":"18th"},{"id":"kw2","text":"Austen"},{"id":"kw3","text":"35"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Jane Austen","pageid":15782,"revision_id":1361713302,"url":"https://en.wikipedia.org/wiki/Jane_Austen","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
