    'approved',
    NOW()
  ),
  (
    'd1000001-0000-4000-8000-10010000001a',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Louvre (French: Musée du Louvre [myze dy luvʁ] ) is a national art museum in Paris, France. It is located on the Right Bank of the Seine in the city''s 1st arrondissement (district) and home to some of the most canonical works of Western art, including the Mona Lisa, Venus de Milo, and Winged Victory."}]},{"type":"paragraph","content":[{"type":"text","text":"The museum is housed in the Louvre Palace, originally built in the late 12th to 13th century under Philip II. Remnants of the Medieval Louvre fortress are visible in the basement of the museum. Due to urban expansion, the fortress eventually lost its defensive function, and in 1546 Francis I converted it into the primary residence of the French kings."}]}]},"keywords":[{"id":"kw1","text":"Winged"},{"id":"kw2","text":"fortress"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Louvre","pageid":17546,"revision_id":1361363244,"url":"https://en.wikipedia.org/wiki/Louvre","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
