  (
    'd1000001-0000-4000-8000-10010000001b',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Ludwig van Beethoven (baptised 17 December 1770 – 26 March 1827) was a German composer, conductor, and pianist."}]},{"type":"paragraph","content":[{"type":"text","text":"Regarded as one of the greatest composers in the history of Western music, he was mentored during the Classical period, and his musical style was a key driver of the transition to Romantic music, and the expansion of instrumental forms such as the symphony, the piano sonata and the string quartet."}]},{"type":"paragraph","content":[{"type":"text","text":"His compositions have attracted extraordinary casual and scholarly interest, and remain among the most performed in the world. Born in Bonn, Beethoven was a musical prodigy. He was initially taught intensively by his father, Johann van Beethoven, and later by Christian Gottlob Neefe."}]}]},"keywords":[{"id":"kw1","text":"Bonn"},{"id":"kw2","text":"Romantic"},{"id":"kw3","text":"Neefe"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Ludwig van Beethoven","pageid":17914,"revision_id":1362140907,"url":"https://en.wikipedia.org/wiki/Ludwig_van_Beethoven","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
