    'd1000001-0000-4000-8000-10010000001c',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Nile is a major north-flowing river in northeast Africa which empties into the Mediterranean Sea. At 7,088 kilometers (4,404 mi) long, it is the longest river in the world, although the volume of water it carries is much smaller than other major rivers such as the Amazon or the Congo."}]},{"type":"paragraph","content":[{"type":"text","text":"The Nile has played a central role in the environmental, economic, and cultural history of Africa for millennia. The Nile has two major tributaries: the White Nile and the Blue Nile. The White Nile is longer and is considered to be the headwaters, yet the Blue Nile contributes over twice the volume of the White Nile."}]}]},"keywords":[{"id":"kw1","text":"4,404"},{"id":"kw2","text":"Congo"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Nile","pageid":21244,"revision_id":1361112005,"url":"https://en.wikipedia.org/wiki/Nile","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
