  (
    'd1000001-0000-4000-8000-10010000001d',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The modern Olympic Games (Olympics; French: Jeux olympiques) are among the biggest sporting events on Earth. They feature summer and winter sports events in which thousands of athletes from 206 countries and territories around the world participate in a variety of athletic competitions."}]},{"type":"paragraph","content":[{"type":"text","text":"The Olympic Games, open to both amateur and professional athletes, involve more than 200 teams, each team representing a sovereign state or territory. The Games often, but not always, substitute for any world championships during the year in which they take place. The Olympics are staged every four years."}]}]},"keywords":[{"id":"kw1","text":"Games"},{"id":"kw2","text":"Olympic"},{"id":"kw3","text":"200"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Olympic Games","pageid":22576,"revision_id":1361541554,"url":"https://en.wikipedia.org/wiki/Olympic_Games","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
