  (
    'd1000001-0000-4000-8000-10010000001e',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Photosynthesis is a system of biological processes by which photopigment-bearing autotrophic organisms, such as most plants, algae and cyanobacteria, convert light energy — typically from sunlight — into the chemical energy necessary to fuel their metabolism."}]},{"type":"paragraph","content":[{"type":"text","text":"The term photosynthesis usually refers to oxygenic photosynthesis, a process that releases oxygen as a byproduct of water splitting."}]},{"type":"paragraph","content":[{"type":"text","text":"Photosynthetic organisms store the converted chemical energy within the bonds of intracellular organic compounds (complex compounds containing carbon), typically carbohydrates like sugars (mainly glucose, fructose and sucrose), starches, phytoglycogen and cellulose."}]}]},"keywords":[{"id":"kw1","text":"Photosynthesis"},{"id":"kw2","text":"typically"},{"id":"kw3","text":"compounds"},{"id":"kw4","text":"energy"},{"id":"kw5","text":"organisms"}],"difficulty":"hard","source":{"provider":"wikipedia","title":"Photosynthesis","pageid":24544,"revision_id":1358838651,"url":"https://en.wikipedia.org/wiki/Photosynthesis","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
    true,
    'approved',
    NOW()
  ),
  (
    'd1000001-0000-4000-8000-10010000001f',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Plate tectonics (from Latin tectonicus, from Ancient Greek τεκτονικός (tektonikós) ''pertaining to building'') is the scientific theory that Earth''s lithosphere comprises a number of large tectonic plates, which have been slowly moving since 3–4 billion years ago. The model builds on the concept of continental drift, an idea developed during the first decades of the 20th century."}]},{"type":"paragraph","content":[{"type":"text","text":"Plate tectonics came to be accepted by geoscientists after seafloor spreading was validated in the mid- to late 1960s. The processes that result in plates and shape Earth''s crust are called tectonics."}]}]},"keywords":[{"id":"kw1","text":"Ancient"},{"id":"kw2","text":"Earth''s"},{"id":"kw3","text":"20th"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Plate tectonics","pageid":24944,"revision_id":1362124384,"url":"https://en.wikipedia.org/wiki/Plate_tectonics","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
