  (
    'd1000001-0000-4000-8000-100100000029',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Artificial intelligence (AI) is the capability of computational systems to perform tasks typically associated with human intelligence, such as learning, reasoning, problem-solving, perception, and decision-making."}]},{"type":"paragraph","content":[{"type":"text","text":"It is a field of research in engineering, mathematics and computer science that develops and studies methods and software that enable machines to perceive their environment and use learning and intelligence to take actions that maximize their chances of achieving defined goals."}]}]},"keywords":[{"id":"kw1","text":"intelligence"},{"id":"kw2","text":"Artificial"},{"id":"kw3","text":"learning"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Artificial intelligence","pageid":1164,"revision_id":1361732815,"url":"https://en.wikipedia.org/wiki/Artificial_intelligence","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
