  ),
  (
    'd1000001-0000-4000-8000-10010000002e',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Magnetic resonance imaging (MRI) is a medical imaging technique used in radiology to generate pictures of the anatomy and the physiological processes inside the body. MRI scanners use strong magnetic fields, magnetic field gradients, and radio waves to form images of the organs in the body."}]},{"type":"paragraph","content":[{"type":"text","text":"MRI does not involve X-rays or the use of ionizing radiation, which distinguishes it from computed tomography (CT) and positron emission tomography (PET) scans. MRI is a medical application of nuclear magnetic resonance (NMR) which can also be used for imaging in other NMR applications, such as NMR spectroscopy."}]}]},"keywords":[{"id":"kw1","text":"NMR"},{"id":"kw2","text":"resonance"},{"id":"kw3","text":"Magnetic"},{"id":"kw4","text":"imaging"},{"id":"kw5","text":"tomography"}],"difficulty":"hard","source":{"provider":"wikipedia","title":"Magnetic resonance imaging","pageid":19446,"revision_id":1360797248,"url":"https://en.wikipedia.org/wiki/Magnetic_resonance_imaging","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
