  (
    'd1000001-0000-4000-8000-10010000002f',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The periodic table, also known as the periodic table of the elements, is an ordered arrangement of the chemical elements into rows (\"periods\") and columns (\"groups\"). An icon of chemistry, the periodic table is widely used in physics and other sciences."}]},{"type":"paragraph","content":[{"type":"text","text":"It is a depiction of the periodic law, which states that when the elements are arranged in order of their atomic numbers an approximate recurrence of their properties is evident. The table is divided into four roughly rectangular areas called blocks. Elements in the same group tend to show similar chemical characteristics."}]}]},"keywords":[{"id":"kw1","text":"table"},{"id":"kw2","text":"elements"},{"id":"kw3","text":"chemical"},{"id":"kw4","text":"periodic"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Periodic table","pageid":23053,"revision_id":1361891479,"url":"https://en.wikipedia.org/wiki/Periodic_table","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
