  (
    'd1000001-0000-4000-8000-100100000030',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Penicillins (P, PCN or PEN) are a group of β-lactam antibiotics originally obtained from Penicillium moulds, principally P. chrysogenum and P. rubens. Most penicillins in clinical use are synthesised by P. chrysogenum using deep tank fermentation and then purified."}]},{"type":"paragraph","content":[{"type":"text","text":"A number of natural penicillins have been discovered, but only two purified compounds are in clinical use: penicillin G (intramuscular or intravenous use) and penicillin V (given by mouth). Penicillins were among the first medications to be effective against many bacterial infections caused by staphylococci and streptococci."}]}]},"keywords":[{"id":"kw1","text":"penicillin"},{"id":"kw2","text":"clinical"},{"id":"kw3","text":"purified"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Penicillin","pageid":23312,"revision_id":1354027758,"url":"https://en.wikipedia.org/wiki/Penicillin","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
