  (
    'd1000001-0000-4000-8000-100100000031',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Renewable energy (also called green energy) is energy made from renewable natural resources that are replenished on a human timescale. The most widely used renewable energy types are solar energy, wind power, and hydropower. Bioenergy and geothermal power are also significant in some countries."}]},{"type":"paragraph","content":[{"type":"text","text":"Renewable energy installations can be large or small and are suited for both urban and rural areas. Renewable energy is often deployed together with further electrification. This has several benefits: electricity can move heat and vehicles efficiently and is clean at the point of consumption."}]}]},"keywords":[{"id":"kw1","text":"power"},{"id":"kw2","text":"Renewable"},{"id":"kw3","text":"energy"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Renewable energy","pageid":25784,"revision_id":1362143895,"url":"https://en.wikipedia.org/wiki/Renewable_energy","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
