  (
    'd1000001-0000-4000-8000-100100000032',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In microeconomics, supply and demand is an economic model of price determination in a market."}]},{"type":"paragraph","content":[{"type":"text","text":"It postulates that, holding all else equal, the unit price for a particular good or other traded item in a perfectly competitive market, will vary until it settles at the market-clearing price, where the quantity demanded equals the quantity supplied such that an economic equilibrium is achieved for price and quantity transacted."}]}]},"keywords":[{"id":"kw1","text":"market"},{"id":"kw2","text":"quantity"},{"id":"kw3","text":"supply"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Supply and demand","pageid":29664,"revision_id":1360794321,"url":"https://en.wikipedia.org/wiki/Supply_and_demand","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
