  (
    'd1000001-0000-4000-8000-100100000033',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A vaccine is a biological preparation that provides active acquired immunity to a particular infectious or malignant disease. The safety and effectiveness of vaccines has been widely studied and verified."}]},{"type":"paragraph","content":[{"type":"text","text":"A vaccine typically contains an agent that resembles a disease-causing microorganism and is often made from weakened or killed forms of the microbe, its toxins, or one of its surface proteins."}]},{"type":"paragraph","content":[{"type":"text","text":"The agent stimulates the immune system to recognize the agent as a threat, destroy it, and recognize further and destroy any of the microorganisms associated with that agent that it may encounter in the future."}]}]},"keywords":[{"id":"kw1","text":"recognize"},{"id":"kw2","text":"destroy"},{"id":"kw3","text":"vaccine"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Vaccine","pageid":32653,"revision_id":1354276133,"url":"https://en.wikipedia.org/wiki/Vaccine","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
