  (
    'd1000001-0000-4000-8000-100100000034',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The World Wide Web (also known as WWW, W3, or simply the Web) is a global interconnected information system that enables content sharing over the Internet. It facilitates access to documents and other web resources according to specific rules of the Hypertext Transfer Protocol (HTTP)."}]},{"type":"paragraph","content":[{"type":"text","text":"The Web was invented by English computer scientist Tim Berners-Lee while at CERN in 1989 and opened to the public in 1993. It was conceived as a \"universal linked information system\". Documents and other media content are made available to the network through web servers and can be accessed by programs such as web browsers."}]}]},"keywords":[{"id":"kw1","text":"documents"},{"id":"kw2","text":"English"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"World Wide Web","pageid":33139,"revision_id":1361950532,"url":"https://en.wikipedia.org/wiki/World_Wide_Web","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
