  (
    'd1000001-0000-4000-8000-100100000035',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"An X-ray is a form of high-energy electromagnetic radiation with a wavelength shorter than those of ultraviolet rays and longer than those of gamma rays."}]},{"type":"paragraph","content":[{"type":"text","text":"Roughly, X-rays have a wavelength ranging from 10 nanometers to 10 picometers, corresponding to frequencies in the range of 30 petahertz to 30 exahertz (3×1016 Hz to 3×1019 Hz) and photon energies in the range of 100 eV to 100 keV, respectively."}]},{"type":"paragraph","content":[{"type":"text","text":"X-rays were discovered in 1895 by the German scientist Wilhelm Conrad Röntgen, who named it X-radiation to signify an unknown type of radiation. X-rays can penetrate many solid substances such as construction materials and living tissue, so X-ray radiography is widely used in medical diagnostics (e. g. , checking for broken bones) and materials science (e. g."}]}]},"keywords":[{"id":"kw1","text":"10"},{"id":"kw2","text":"Wilhelm"},{"id":"kw3","text":"materials"},{"id":"kw4","text":"100"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"X-ray","pageid":34197,"revision_id":1360545105,"url":"https://en.wikipedia.org/wiki/X-ray","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
