  (
    'd1000001-0000-4000-8000-100100000036',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"In economics, inflation is an increase in the average price of goods and services in terms of money. This increase is measured using a price index, typically a consumer price index (CPI). When the general price level rises, each unit of currency buys fewer goods and services; consequently, inflation corresponds to a reduction in the purchasing power of money."}]},{"type":"paragraph","content":[{"type":"text","text":"The opposite of inflation is deflation, a decrease in the general price level of goods and services. The common measure of inflation is the inflation rate, the annualized percentage change in a general price index."}]}]},"keywords":[{"id":"kw1","text":"general"},{"id":"kw2","text":"index"},{"id":"kw3","text":"level"},{"id":"kw4","text":"money"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Inflation","pageid":38286,"revision_id":1361742939,"url":"https://en.wikipedia.org/wiki/Inflation","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
