  (
    'd1000001-0000-4000-8000-100100000038',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Machine learning (ML) is a field of study in artificial intelligence concerned with the development and study of statistical algorithms that can learn from data and generalize to unseen data, and thus perform tasks without being explicitly programmed."}]},{"type":"paragraph","content":[{"type":"text","text":"Advances in the field of deep learning have allowed neural networks, a class of statistical algorithms, to surpass many previous machine learning approaches in performance. Statistics and mathematical optimisation methods compose the foundations of machine learning."}]}]},"keywords":[{"id":"kw1","text":"learning"},{"id":"kw2","text":"statistical"}],"difficulty":"easy","source":{"provider":"wikipedia","title":"Machine learning","pageid":233488,"revision_id":1360517605,"url":"https://en.wikipedia.org/wiki/Machine_learning","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
    true,
