  ),
  (
    'd1000001-0000-4000-8000-10010000003c',
    'a1000001-0000-4000-8000-000000000001',
    '{"passage":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Cryptography, or cryptology, is the practice and study of techniques for secure communication in the presence of adversarial behavior. More generally, cryptography is about constructing and analyzing protocols that prevent third parties or the public from reading private messages."}]},{"type":"paragraph","content":[{"type":"text","text":"Modern cryptography exists at the intersection of the disciplines of mathematics, computer science, information security, electrical engineering, digital signal processing, physics, and others. Core concepts related to information security (data confidentiality, data integrity, authentication and non-repudiation) are also central to cryptography."}]}]},"keywords":[{"id":"kw1","text":"information"},{"id":"kw2","text":"security"},{"id":"kw3","text":"Cryptography"}],"difficulty":"medium","source":{"provider":"wikipedia","title":"Cryptography","pageid":18934432,"revision_id":1360559240,"url":"https://en.wikipedia.org/wiki/Cryptography","license":"CC BY-SA 4.0","retrieved_at":"2026-07-02T11:41:21.820Z"}}'::jsonb,
